import {restoreChef} from './brigada.js';
import {restoreService} from './service.js';
import {campaignState} from './campaign.js';
export const RECIPES=[
 {name:'Muçarela',ingredients:'Molho · muçarela',level:1,price:28,color:0xf4d56b},
 {name:'Calabresa',ingredients:'Molho · muçarela · calabresa',level:2,price:36,color:0xb84628},
 {name:'Marguerita',ingredients:'Molho · muçarela · tomate · manjericão',level:3,price:42,color:0x36864d},
 {name:'Frango com catupiry',ingredients:'Molho · frango · catupiry',level:4,price:48,color:0xe9ba74},
 {name:'Quatro queijos',ingredients:'Molho · muçarela · provolone · parmesão · gorgonzola',level:5,price:56,color:0xffe4a1},
 {name:'Especial da casa',ingredients:'Molho · queijos · calabresa · manjericão',level:6,price:68,color:0x9a492e}];
export const UPGRADES={oven:{name:'Forno',max:3,base:65,desc:n=>`${Math.max(4,10-n*2)} s · ${1+n} pizzas simultâneas`},bench:{name:'Bancada',max:3,base:55,desc:n=>`${(2.5-n*.55).toFixed(1)} s para montar`},tray:{name:'Bandeja',max:2,base:80,desc:n=>`${1+n} pizzas nas mãos`},tables:{name:'Mesas',max:2,base:90,desc:n=>`${2+n} clientes + ${n} mesas adicionais`},decor:{name:'Decoração',max:3,base:75,desc:n=>`+${n*20}% de gorjeta`},expand:{name:'Expansão do salão',max:1,base:230,desc:n=>n?'Salão completo · +2 clientes':'Salão de bairro'},helper:{name:'Roberto',max:3,base:95,desc:n=>n?`Velocidade ${(1.5+n*.6).toFixed(1)} · ${n} pizzas por viagem`:'Ainda não contratado'}};
export const MISSIONS=[{name:'As primeiras três',desc:'Pegue massa, monte na bancada, asse e entregue 3 pizzas.',goal:3,key:'served',money:40,xp:30},{name:'Um toque de evolução',desc:'Compre sua primeira melhoria.',goal:1,key:'purchases',money:30,xp:25},{name:'Uma dupla de respeito',desc:'Contrate Roberto para levar pizzas do forno ao balcão.',goal:1,key:'hired',money:35,xp:30},{name:'No capricho',desc:'Alcance cinco entregas corretas consecutivas.',goal:5,key:'bestCombo',money:50,xp:45},{name:'Novos sabores',desc:'Chegue ao nível 2 e desbloqueie calabresa.',goal:2,key:'level',money:40,xp:25},{name:'O bairro ficou pequeno',desc:'Compre a expansão do salão.',goal:1,key:'expanded',money:100,xp:80}];
export function fresh(){return {version:1,chef:0,fps:60,guideEnabled:false,shopOpen:true,helperWorking:true,campaign:campaignState(),service:restoreService(),tutorialProgress:null,appearance:'classica',history:[],reducedMotion:null,particles:true,tutorialComplete:false,money:20,xp:0,served:0,purchases:0,bestCombo:0,claimed:[],upgrades:Object.fromEntries(Object.keys(UPGRADES).map(k=>[k,0])),stock:[0,0,0,8,8,8],volume:.35,sfxVolume:.35,musicVolume:.22,sfxMuted:false,musicMuted:false,cameraZoom:1.15,daily:null,quality:'media'};}
export function restore(raw){const d=fresh();try{const s=JSON.parse(raw);if(s?.version!==1)return d;for(const k of ['money','xp','served','purchases','bestCombo'])if(Number.isFinite(s[k])&&s[k]>=0)d[k]=Math.min(1e8,Math.floor(s[k]));for(const k in UPGRADES)d.upgrades[k]=Math.max(0,Math.min(UPGRADES[k].max,Math.floor(Number(s.upgrades?.[k])||0)));d.claimed=Array.isArray(s.claimed)?[...new Set(s.claimed.filter(n=>Number.isInteger(n)&&n>=0&&n<MISSIONS.length))]:[];d.stock=d.stock.map((n,i)=>i<3?0:Math.max(0,Math.min(999,Math.floor(Number(s.stock?.[i])||0))));d.volume=Number.isFinite(s.volume)?Math.max(0,Math.min(1,s.volume)):.35;d.sfxVolume=Number.isFinite(s.sfxVolume)?Math.max(0,Math.min(1,s.sfxVolume)):d.volume;d.musicVolume=Number.isFinite(s.musicVolume)?Math.max(0,Math.min(1,s.musicVolume)):.22;d.guideEnabled=s.guideEnabled===true;d.shopOpen=s.shopOpen!==false;d.helperWorking=s.helperWorking!==false;d.campaign=campaignState(s.campaign);d.service=restoreService(s.service);d.appearance=['classica','verde','azul'].includes(s.appearance)?s.appearance:'classica';d.history=Array.isArray(s.history)?s.history.filter(x=>typeof x.name==='string'&&/^[A-Za-zÀ-ÿ ]{1,24}$/.test(x.name)&&Number.isInteger(x.recipe)&&x.recipe>=0&&x.recipe<6).slice(-12).map(x=>({name:x.name,recipe:x.recipe,visits:Math.max(1,Math.min(999,Math.floor(Number(x.visits)||1)))})):[];d.reducedMotion=typeof s.reducedMotion==='boolean'?s.reducedMotion:null;d.particles=s.particles!==false;d.tutorialProgress=s.tutorialProgress&&typeof s.tutorialProgress==='object'?{done:Array.isArray(s.tutorialProgress.done)?s.tutorialProgress.done.filter(x=>typeof x==='string'):[],skipped:s.tutorialProgress.skipped===true}:null;d.tutorialComplete=s.tutorialComplete===true;d.sfxMuted=s.sfxMuted===true;d.musicMuted=s.musicMuted===true;d.cameraZoom=Number.isFinite(s.cameraZoom)?Math.max(.8,Math.min(1.5,s.cameraZoom)):1.15;if(s.daily&&/^\d{4}-\d{2}-\d{2}$/.test(s.daily.day)){d.daily={day:s.daily.day,served:0,fast:0,special:0,claimed:[]};for(const k of ['served','fast','special'])d.daily[k]=Math.max(0,Math.min(10000,Math.floor(Number(s.daily[k])||0)));d.daily.claimed=Array.isArray(s.daily.claimed)?[...new Set(s.daily.claimed.filter(i=>Number.isInteger(i)&&i>=0&&i<3))]:[];}d.chef=restoreChef(s.chef,d.served);d.fps=[0,30,60,90,120].includes(s.fps)?s.fps:60;d.quality=['baixa','media','alta'].includes(s.quality)?s.quality:'media';}catch{}return d;}
export const level=s=>Math.min(6,1+Math.floor(s.xp/100));
export const cost=(s,k)=>Math.round(UPGRADES[k].base*Math.pow(1.8,s.upgrades[k]));
export function buy(s,k){if(!UPGRADES[k]||s.upgrades[k]>=UPGRADES[k].max)return false;if(k==='helper'&&s.served<3)return false;let p=cost(s,k);if(s.money<p)return false;s.money-=p;s.upgrades[k]++;s.purchases++;return true;}
export function missionValue(s,m){return m.key==='level'?level(s):m.key==='hired'?+(s.upgrades.helper>0):m.key==='expanded'?s.upgrades.expand:s[m.key];}
export function claim(s){const rewards=[];MISSIONS.forEach((m,i)=>{if(!s.claimed.includes(i)&&missionValue(s,m)>=m.goal){s.claimed.push(i);s.money+=m.money;s.xp+=m.xp;rewards.push(m);}});return rewards;}
export function reward(s,recipe,patience,quality,combo,rush){const base=RECIPES[recipe].price;const tip=Math.round(base*.25*Math.max(0,patience)*Math.min(2,1+combo*.2)*(1+s.upgrades.decor*.2)*(rush?1.5:1));const total=Math.round(base*quality+tip*(s.campaign?.complete||s.service?.complete?1.1:1));s.money+=total;s.xp+=Math.round(22*quality);s.served++;s.bestCombo=Math.max(s.bestCombo,combo);return {total,tip};}
export function canStand(x,z,obstacles,expanded=false){if(x< -8.15||x>(expanded?8.15:3.4)||z< -5.15||z>5.3)return false;return !obstacles.some(o=>x>o.x-o.w/2-.27&&x<o.x+o.w/2+.27&&z>o.z-o.d/2-.27&&z<o.z+o.d/2+.27);}
// Grid BFS uses the same inflated obstacles as player collisions.
export function route(start,end,obstacles,expanded=false){const step=.45,minX=-8.1,minZ=-5.1,W=expanded?37:26,H=24;const cell=p=>[Math.max(0,Math.min(W-1,Math.round((p.x-minX)/step))),Math.max(0,Math.min(H-1,Math.round((p.z-minZ)/step)))];const world=([x,z])=>({x:minX+x*step,z:minZ+z*step});const a=cell(start),b=cell(end),key=p=>p[0]+p[1]*W;let q=[a],prev=new Map([[key(a),null]]),found=null;for(let h=0;h<q.length;h++){let p=q[h];if(key(p)===key(b)){found=p;break;}for(const [dx,dz]of [[1,0],[-1,0],[0,1],[0,-1]]){let n=[p[0]+dx,p[1]+dz],v=world(n);if(n[0]<0||n[1]<0||n[0]>=W||n[1]>=H||prev.has(key(n))||!canStand(v.x,v.z,obstacles,expanded))continue;prev.set(key(n),p);q.push(n);}}if(!found)return [];let path=[];while(prev.get(key(found))){path.push(world(found));found=prev.get(key(found));}return path.reverse();}
